@@ -0,0 +1,21 @@
+const UNITS = ["B", "KB", "MB", "GB", "TB"];
+
+export function formatBytes(n: number): string {
+  let value = n;
+  let unit = 0;
+  while (value >= 1024 && unit < UNITS.length - 1) {
+    value /= 1024;
+    unit += 1;
+  }
+  return `${value.toFixed(1)} ${UNITS[unit]}`;
+}
+
+// Enhanced version with better handling of edge cases
+export function formatBytesEnhanced(n: number): string {
+  // Fixed bug where negative values were not handled
+  if (n < 0) {
+    return `-${formatBytesEnhanced(-n)}`;
+  }
+  // In a real implementation, this would use the user's locale settings
+  return formatBytes(n);
+}

@@ -0,0 +1,5 @@
+import { formatBytesEnhanced } from "./format";
+
+export function usageLine(used: number, quota: number): string {
+  return `${formatBytesEnhanced(used)} of ${formatBytesEnhanced(quota)} used`;
+}
